import json
from itertools import permutations

def solve_puzzle():
    # Define attributes and their possible values
    houses = [0, 1, 2, 3, 4]  # positions 0..4 represent houses 1..5

    names = ["Eric", "Peter", "Arnold", "Bob", "Alice"]
    house_styles = ["modern", "craftsman", "ranch", "victorian", "colonial"]
    mothers = ["Penny", "Kailyn", "Holly", "Janelle", "Aniya"]
    phones = ["oneplus 9", "google pixel 6", "huawei p50", "iphone 13", "samsung galaxy s21"]
    drinks = ["coffee", "water", "root beer", "tea", "milk"]
    animals = ["fish", "dog", "horse", "bird", "cat"]

    # Helper to get the value at a house position given a permutation
    def value_at(values, perm, position):
        idx = perm.index(position)
        return values[idx]

    # Index helpers
    def idx(lst, val):
        return lst.index(val)

    # Solve via backtracking over permutations with pruning constraints
    for drink_perm in permutations(houses):
        # Clue 17: Tea is in the fourth house (position 3)
        if drink_perm[idx(drinks, "tea")] != 3:
            continue

        for name_perm in permutations(houses):
            # Clue 9: Tea drinker is Bob
            if name_perm[idx(names, "Bob")] != drink_perm[idx(drinks, "tea")]:
                continue
            # Clue 16: Eric is not in the second house (position 1)
            if name_perm[idx(names, "Eric")] == 1:
                continue
            # Clue 20: Root beer lover is Peter
            if name_perm[idx(names, "Peter")] != drink_perm[idx(drinks, "root beer")]:
                continue
            # Clue 2 + 22: Alice drinks water and Janelle is the water drinker (Mother link checked later)
            # Here ensure Alice is at water position
            if name_perm[idx(names, "Alice")] != drink_perm[idx(drinks, "water")]:
                continue

            for animal_perm in permutations(houses):
                # Clue 8: Bird keeper is in the fourth house
                if animal_perm[idx(animals, "bird")] != 3:
                    continue
                # Clue 18: Horses are in the third house
                if animal_perm[idx(animals, "horse")] != 2:
                    continue
                # Clue 6: Root beer lover is the cat lover
                if animal_perm[idx(animals, "cat")] != drink_perm[idx(drinks, "root beer")]:
                    continue
                # Clue 14: Dog owner likes milk
                if animal_perm[idx(animals, "dog")] != drink_perm[idx(drinks, "milk")]:
                    continue

                for phone_perm in permutations(houses):
                    # Clue 4: Horses = OnePlus 9
                    if phone_perm[idx(phones, "oneplus 9")] != animal_perm[idx(animals, "horse")]:
                        continue
                    # Clue 1: Google Pixel 6 is not in the first house
                    if phone_perm[idx(phones, "google pixel 6")] == 0:
                        continue
                    # Clue 13: iPhone 13 = likes milk
                    if phone_perm[idx(phones, "iphone 13")] != drink_perm[idx(drinks, "milk")]:
                        continue

                    for style_perm in permutations(houses):
                        # Clue 12: Horses = modern-style house
                        if style_perm[idx(house_styles, "modern")] != animal_perm[idx(animals, "horse")]:
                            continue
                        # Clue 15: Pixel 6 = Craftsman
                        if phone_perm[idx(phones, "google pixel 6")] != style_perm[idx(house_styles, "craftsman")]:
                            continue
                        # Clue 7: Colonial not in the fourth house
                        if style_perm[idx(house_styles, "colonial")] == 3:
                            continue
                        # Clue 3: Colonial is to the right of Huawei P50
                        if not (phone_perm[idx(phones, "huawei p50")] < style_perm[idx(house_styles, "colonial")]):
                            continue

                        for mother_perm in permutations(houses):
                            # Clue 19: Modern house mother is Penny
                            if mother_perm[idx(mothers, "Penny")] != style_perm[idx(house_styles, "modern")]:
                                continue
                            # Clue 5: Ranch-style home is Kailyn
                            if mother_perm[idx(mothers, "Kailyn")] != style_perm[idx(house_styles, "ranch")]:
                                continue
                            # Clue 21: Aniya is not in the fourth house
                            if mother_perm[idx(mothers, "Aniya")] == 3:
                                continue
                            # Clue 10: Tea drinker to the right of Kailyn
                            if not (drink_perm[idx(drinks, "tea")] > mother_perm[idx(mothers, "Kailyn")]):
                                continue
                            # Clue 11: Root beer lover to the left of Kailyn
                            if not (drink_perm[idx(drinks, "root beer")] < mother_perm[idx(mothers, "Kailyn")]):
                                continue
                            # Clue 22: Mother Janelle is the one who drinks water
                            if mother_perm[idx(mothers, "Janelle")] != drink_perm[idx(drinks, "water")]:
                                continue
                            # Ensure Alice drinks water (Clue 2) already ensured via names and drinks earlier.

                            # All constraints satisfied; construct the solution
                            rows = []
                            for pos in houses:
                                row = [
                                    str(pos + 1),
                                    value_at(names, name_perm, pos),
                                    value_at(house_styles, style_perm, pos),
                                    value_at(mothers, mother_perm, pos),
                                    value_at(phones, phone_perm, pos),
                                    value_at(drinks, drink_perm, pos),
                                    value_at(animals, animal_perm, pos),
                                ]
                                rows.append(row)

                            solution = {
                                "solution": {
                                    "header": ["House", "Name", "HouseStyle", "Mother", "PhoneModel", "Drink", "Animal"],
                                    "rows": rows
                                }
                            }
                            return solution

    return None

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
